import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

namespace lnorm_detail {
constexpr int kThreads = 256;
constexpr int kMaxSplits = 256;
constexpr int64_t kTargetBlocks = 4096;
__device__ __forceinline__ float ldcs1(const float* p) { return __ldcs(p); }
__device__ __forceinline__ float4 ldcs4(const float4* p) { return __ldcs(p); }
__device__ __forceinline__ void stcs1(float* p, float v) { __stcs(p, v); }
__device__ __forceinline__ void stcs4(float4* p, float4 v) { __stcs(p, v); }
__device__ __forceinline__ float ldg1(const float* p) { return __ldg(p); }
__device__ __forceinline__ float4 ldg4(const float4* p) { return __ldg(p); }
__device__ __forceinline__ void accum4(float4 v, float shift, double& s, double& q) {
  float d0 = v.x - shift;
  float d1 = v.y - shift;
  float d2 = v.z - shift;
  float d3 = v.w - shift;
  s += (double)((d0 + d1) + (d2 + d3));
  q += (double)fmaf(d0, d0, fmaf(d1, d1, fmaf(d2, d2, d3 * d3)));
}
__device__ __forceinline__ float4 norm4(float4 xv, float4 wv, float4 bv,
                                        float shift, float mean_d, float rstd) {
  float4 o;
  o.x = fmaf(((xv.x - shift) - mean_d) * rstd, wv.x, bv.x);
  o.y = fmaf(((xv.y - shift) - mean_d) * rstd, wv.y, bv.y);
  o.z = fmaf(((xv.z - shift) - mean_d) * rstd, wv.z, bv.z);
  o.w = fmaf(((xv.w - shift) - mean_d) * rstd, wv.w, bv.w);
  return o;
}
// Split each normalization row across multiple CTAs. This keeps the same
// shifted two-pass semantics, but exposes enough CTAs to fill the GPU when
// the batch/row count M is small and N is very large.
__global__ __launch_bounds__(kThreads)
void layernorm_fwd_partial_kernel(const float* __restrict__ X,
                                  double2* __restrict__ partials,
                                  int64_t N,
                                  int splits)
{
  const int64_t bid = blockIdx.x;
  const int64_t row = bid / splits;
  const int split = (int)(bid - row * splits);
  const int tid = threadIdx.x;
  const float* xrow = X + row * N;
  Tensor gX = make_tensor(make_gmem_ptr(xrow), make_shape(N), make_stride(Int<1>{}));
  const bool vec_ok = ((N & 3) == 0);
  const int64_t NV = vec_ok ? (N >> 2) : 0;
  Tensor gXv = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(xrow)),
                           make_shape(NV), make_stride(Int<1>{}));
  const float shift = gX(0);
  double s0 = 0.0, s1 = 0.0, s2 = 0.0, s3 = 0.0;
  double q0 = 0.0, q1 = 0.0, q2 = 0.0, q3 = 0.0;
  if (vec_ok) {
    const int64_t per = (NV + splits - 1) / splits;
    const int64_t vb = (int64_t)split * per;
    const int64_t ve = min(NV, vb + per);
    int64_t i = vb + tid;
    for (; i + 3 * kThreads < ve; i += 4 * kThreads) {
      accum4(ldcs4(&gXv(i)), shift, s0, q0);
      accum4(ldcs4(&gXv(i + kThreads)), shift, s1, q1);
      accum4(ldcs4(&gXv(i + 2 * kThreads)), shift, s2, q2);
      accum4(ldcs4(&gXv(i + 3 * kThreads)), shift, s3, q3);
    }
    for (; i < ve; i += kThreads) {
      accum4(ldcs4(&gXv(i)), shift, s0, q0);
    }
  } else {
    const int64_t per = (N + splits - 1) / splits;
    const int64_t b = (int64_t)split * per;
    const int64_t e = min(N, b + per);
    for (int64_t j = b + tid; j < e; j += kThreads) {
      float d = ldcs1(&gX(j)) - shift;
      s0 += (double)d;
      q0 += (double)d * (double)d;
    }
  }
  double lsum = (s0 + s1) + (s2 + s3);
  double lsq  = (q0 + q1) + (q2 + q3);
  #pragma unroll
  for (int off = 16; off > 0; off >>= 1) {
    lsum += __shfl_down_sync(0xffffffffu, lsum, off);
    lsq  += __shfl_down_sync(0xffffffffu, lsq,  off);
  }
  constexpr int kWarps = kThreads / 32;
  __shared__ double s_wsum[kWarps];
  __shared__ double s_wsq [kWarps];
  const int lane = tid & 31;
  const int warp = tid >> 5;
  if (lane == 0) {
    s_wsum[warp] = lsum;
    s_wsq [warp] = lsq;
  }
  __syncthreads();
  if (warp == 0) {
    double a = (lane < kWarps) ? s_wsum[lane] : 0.0;
    double q = (lane < kWarps) ? s_wsq [lane] : 0.0;
    #pragma unroll
    for (int off = 16; off > 0; off >>= 1) {
      a += __shfl_down_sync(0xffffffffu, a, off);
      q += __shfl_down_sync(0xffffffffu, q, off);
    }
    if (lane == 0) {
      partials[bid] = make_double2(a, q);
    }
  }
}
__global__ __launch_bounds__(kThreads)
void layernorm_fwd_normalize_kernel(const float* __restrict__ X,
                                    const float* __restrict__ W,
                                    const float* __restrict__ B,
                                    float* __restrict__ Y,
                                    const double2* __restrict__ partials,
                                    int64_t N,
                                    int splits,
                                    float eps)
{
  const int64_t bid = blockIdx.x;
  const int64_t row = bid / splits;
  const int split = (int)(bid - row * splits);
  const int tid = threadIdx.x;
  const float* xrow = X + row * N;
  float*       yrow = Y + row * N;
  Tensor gX = make_tensor(make_gmem_ptr(xrow), make_shape(N), make_stride(Int<1>{}));
  Tensor gY = make_tensor(make_gmem_ptr(yrow), make_shape(N), make_stride(Int<1>{}));
  Tensor gW = make_tensor(make_gmem_ptr(W),    make_shape(N), make_stride(Int<1>{}));
  Tensor gB = make_tensor(make_gmem_ptr(B),    make_shape(N), make_stride(Int<1>{}));
  const bool vec_ok = ((N & 3) == 0);
  const int64_t NV = vec_ok ? (N >> 2) : 0;
  Tensor gXv = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(xrow)),
                           make_shape(NV), make_stride(Int<1>{}));
  Tensor gYv = make_tensor(make_gmem_ptr(reinterpret_cast<float4*>(yrow)),
                           make_shape(NV), make_stride(Int<1>{}));
  Tensor gWv = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(W)),
                           make_shape(NV), make_stride(Int<1>{}));
  Tensor gBv = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(B)),
                           make_shape(NV), make_stride(Int<1>{}));
  const float shift = gX(0);
  // Deterministically reduce this row's per-split partial sums. Because
  // splits <= kMaxSplits (== kThreads), each thread loads at most one
  // partial and a plain block reduction yields the row totals. This
  // replaces the stats memset + global atomicAdd reduction entirely.
  const double2 p = (tid < splits) ? partials[row * (int64_t)splits + tid]
                                   : make_double2(0.0, 0.0);
  double rsum = p.x;
  double rsq  = p.y;
  #pragma unroll
  for (int off = 16; off > 0; off >>= 1) {
    rsum += __shfl_down_sync(0xffffffffu, rsum, off);
    rsq  += __shfl_down_sync(0xffffffffu, rsq,  off);
  }
  constexpr int kWarps = kThreads / 32;
  __shared__ double s_rsum[kWarps];
  __shared__ double s_rsq [kWarps];
  __shared__ double s_bcast[2];
  const int lane = tid & 31;
  const int warp = tid >> 5;
  if (lane == 0) {
    s_rsum[warp] = rsum;
    s_rsq [warp] = rsq;
  }
  __syncthreads();
  if (warp == 0) {
    double a = (lane < kWarps) ? s_rsum[lane] : 0.0;
    double q = (lane < kWarps) ? s_rsq [lane] : 0.0;
    #pragma unroll
    for (int off = 16; off > 0; off >>= 1) {
      a += __shfl_down_sync(0xffffffffu, a, off);
      q += __shfl_down_sync(0xffffffffu, q, off);
    }
    if (lane == 0) {
      s_bcast[0] = a;
      s_bcast[1] = q;
    }
  }
  __syncthreads();
  const double invN = 1.0 / (double)N;
  const double md = s_bcast[0] * invN;
  double var = s_bcast[1] * invN - md * md;
  if (var < 0.0) var = 0.0;
  const float mean_d = (float)md;
  const float rstd = (float)(1.0 / sqrt(var + (double)eps));
  if (vec_ok) {
    const int64_t per = (NV + splits - 1) / splits;
    const int64_t vb = (int64_t)split * per;
    const int64_t ve = min(NV, vb + per);
    int64_t i = vb + tid;
    for (; i + 3 * kThreads < ve; i += 4 * kThreads) {
      stcs4(&gYv(i), norm4(ldcs4(&gXv(i)), ldg4(&gWv(i)), ldg4(&gBv(i)), shift, mean_d, rstd));
      stcs4(&gYv(i + kThreads), norm4(ldcs4(&gXv(i + kThreads)), ldg4(&gWv(i + kThreads)), ldg4(&gBv(i + kThreads)), shift, mean_d, rstd));
      stcs4(&gYv(i + 2 * kThreads), norm4(ldcs4(&gXv(i + 2 * kThreads)), ldg4(&gWv(i + 2 * kThreads)), ldg4(&gBv(i + 2 * kThreads)), shift, mean_d, rstd));
      stcs4(&gYv(i + 3 * kThreads), norm4(ldcs4(&gXv(i + 3 * kThreads)), ldg4(&gWv(i + 3 * kThreads)), ldg4(&gBv(i + 3 * kThreads)), shift, mean_d, rstd));
    }
    for (; i < ve; i += kThreads) {
      stcs4(&gYv(i), norm4(ldcs4(&gXv(i)), ldg4(&gWv(i)), ldg4(&gBv(i)), shift, mean_d, rstd));
    }
  } else {
    const int64_t per = (N + splits - 1) / splits;
    const int64_t b = (int64_t)split * per;
    const int64_t e = min(N, b + per);
    for (int64_t j = b + tid; j < e; j += kThreads) {
      float d = ldcs1(&gX(j)) - shift;
      stcs1(&gY(j), fmaf((d - mean_d) * rstd, ldg1(&gW(j)), ldg1(&gB(j))));
    }
  }
}
} // namespace lnorm_detail
torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps) {
  TORCH_CHECK(x.is_cuda() && weight.is_cuda() && bias.is_cuda(),
              "x, weight and bias must be CUDA tensors");
  TORCH_CHECK(x.scalar_type() == at::kFloat &&
              weight.scalar_type() == at::kFloat &&
              bias.scalar_type() == at::kFloat,
              "Expect float32 tensors");
  TORCH_CHECK(weight.numel() == bias.numel(), "weight and bias must have same numel");
  const int64_t N = weight.numel();
  TORCH_CHECK(N > 0, "normalized dimension must be > 0");
  const int wd = weight.dim();
  TORCH_CHECK(x.dim() >= wd, "x must have at least as many dims as weight");
  for (int k = 0; k < wd; ++k) {
    TORCH_CHECK(x.size(x.dim() - wd + k) == weight.size(k),
                "Trailing dims of x must match normalized_shape");
  }
  TORCH_CHECK(x.numel() % N == 0, "x.numel() must be divisible by weight.numel()");
  const int64_t M = x.numel() / N;
  TORCH_CHECK(M > 0 && M <= 0x7fffffff, "Invalid number of rows");
  auto xc = x.contiguous();
  auto wc = weight.contiguous();
  auto bc = bias.contiguous();
  auto y = torch::empty_like(xc);
  int64_t splits = (lnorm_detail::kTargetBlocks + M - 1) / M;
  if (splits < 1) splits = 1;
  if (splits > lnorm_detail::kMaxSplits) splits = lnorm_detail::kMaxSplits;
  const int64_t by_n = (N + lnorm_detail::kThreads - 1) / lnorm_detail::kThreads;
  if (splits > by_n) splits = by_n;
  const int64_t by_grid = 0x7fffffff / M;
  if (splits > by_grid) splits = by_grid;
  if (splits < 1) splits = 1;
  dim3 grid((unsigned)(M * splits));
  dim3 block(lnorm_detail::kThreads);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  auto partials = torch::empty({M * splits * 2}, xc.options().dtype(at::kDouble));
  double2* partials_ptr = reinterpret_cast<double2*>(partials.data_ptr<double>());
  lnorm_detail::layernorm_fwd_partial_kernel<<<grid, block, 0, stream>>>(
      xc.data_ptr<float>(),
      partials_ptr,
      N,
      (int)splits);
  lnorm_detail::layernorm_fwd_normalize_kernel<<<grid, block, 0, stream>>>(
      xc.data_ptr<float>(),
      wc.data_ptr<float>(),
      bc.data_ptr<float>(),
      y.data_ptr<float>(),
      partials_ptr,
      N,
      (int)splits,
      (float)eps);
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "layernorm split-row kernels failed: ",
              cudaGetErrorString(err));
  return y;
}
"""

cute_layernorm_ext = load_inline(
    name="cute_layernorm_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["layernorm_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Layer Normalization implemented with a single custom CUDA/CuTe kernel.

    One thread block cooperatively normalizes one row of length
    N = prod(normalized_shape): pass 1 computes shifted sum and
    sum-of-squares with a block reduction (stable for large-mean inputs),
    pass 2 writes the affine-transformed normalized output. All global
    memory accesses go through CuTe tensors with float4 vectorization.
    """
    def __init__(self, normalized_shape) -> None:
        super().__init__()
        if isinstance(normalized_shape, int):
            normalized_shape = (normalized_shape,)
        self.normalized_shape = tuple(normalized_shape)
        self.eps = 1e-5

        # Same initialization as nn.LayerNorm (weight=1, bias=0).
        self.weight = nn.Parameter(torch.ones(self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(self.normalized_shape))

        self._ext = cute_layernorm_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if x.is_cuda and x.dtype == torch.float32:
            return self._ext.layernorm_forward(
                x.contiguous(),
                self.weight.contiguous(),
                self.bias.contiguous(),
                float(self.eps),
            )
        return F.layer_norm(x, self.normalized_shape, self.weight, self.bias, self.eps)

