// Split each normalization row across multiple CTAs. This keeps the same
// shifted two-pass semantics, but exposes enough CTAs to fill the GPU when
// the batch/row count M is small and N is very large.
__global__ __launch_bounds__(kThreads)
void layernorm_fwd_partial_kernel(const float* __restrict__ X,
                                  double* __restrict__ dsum,
                                  double* __restrict__ dsq,
                                  int64_t N,
                                  int splits)
{
  const int64_t bid = blockIdx.x;
  const int64_t row = bid / splits;
  const int split = (int)(bid - row * splits);
  const int tid = threadIdx.x;
  const float* xrow = X + row * N;
  Tensor gX = make_tensor(make_gmem_ptr(xrow), make_shape(N), make_stride(Int<1>{}));
  const bool vec_ok = ((N & 3) == 0);
  const int64_t NV = vec_ok ? (N >> 2) : 0;
  Tensor gXv = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(xrow)),
                           make_shape(NV), make_stride(Int<1>{}));
  const float shift = gX(0);
  double s0 = 0.0, s1 = 0.0, s2 = 0.0, s3 = 0.0;
  double q0 = 0.0, q1 = 0.0, q2 = 0.0, q3 = 0.0;
  if (vec_ok) {
    const int64_t per = (NV + splits - 1) / splits;
    const int64_t vb = (int64_t)split * per;
    const int64_t ve = min(NV, vb + per);
    int64_t i = vb + tid;
    for (; i + 3 * kThreads < ve; i += 4 * kThreads) {
      accum4(ldcs4(&gXv(i)), shift, s0, q0);
      accum4(ldcs4(&gXv(i + kThreads)), shift, s1, q1);
      accum4(ldcs4(&gXv(i + 2 * kThreads)), shift, s2, q2);
      accum4(ldcs4(&gXv(i + 3 * kThreads)), shift, s3, q3);
    }
    for (; i < ve; i += kThreads) {
      accum4(ldcs4(&gXv(i)), shift, s0, q0);
    }
  } else {
    const int64_t per = (N + splits - 1) / splits;
    const int64_t b = (int64_t)split * per;
    const int64_t e = min(N, b + per);
    for (int64_t j = b + tid; j < e; j += kThreads) {
      float d = ldcs1(&gX(j)) - shift;
      s0 += (double)d;
      q0 += (double)d * (double)d;
    }
  }
  double lsum = (s0 + s1) + (s2 + s3);
  double lsq  = (q0 + q1) + (q2 + q3);
  #pragma unroll
  for (int off = 16; off > 0; off >>= 1) {
    lsum += __shfl_down_sync(0xffffffffu, lsum, off);
    lsq  += __shfl_down_sync(0xffffffffu, lsq,  off);
  }
  constexpr int kWarps = kThreads / 32;
  __shared__ double s_wsum[kWarps];
  __shared__ double s_wsq [kWarps];
  const int lane = tid & 31;
  const int warp = tid >> 5;
  if (lane == 0) {
    s_wsum[warp] = lsum;
    s_wsq [warp] = lsq;
  }
  __syncthreads();
  if (warp == 0) {
    double a = (lane < kWarps) ? s_wsum[lane] : 0.0;
    double q = (lane < kWarps) ? s_wsq [lane] : 0.0;
    #pragma unroll
    for (int off = 16; off > 0; off >>= 1) {
      a += __shfl_down_sync(0xffffffffu, a, off);
      q += __shfl_down_sync(0xffffffffu, q, off);
    }
    if (lane == 0) {
      atomicAdd(&dsum[row], a);
      atomicAdd(&dsq [row], q);
    }
  }
}
__global__ __launch_bounds__(kThreads)
void layernorm_fwd_normalize_kernel(const float* __restrict__ X,
                                    const float* __restrict__ W,
                                    const float* __restrict__ B,
                                    float* __restrict__ Y,
                                    const double* __restrict__ dsum,
                                    const double* __restrict__ dsq,
                                    int64_t N,
                                    int splits,
                                    float eps)
{
  const int64_t bid = blockIdx.x;
  const int64_t row = bid / splits;
  const int split = (int)(bid - row * splits);
  const int tid = threadIdx.x;
  const float* xrow = X + row * N;
  float*       yrow = Y + row * N;
  Tensor gX = make_tensor(make_gmem_ptr(xrow), make_shape(N), make_stride(Int<1>{}));
  Tensor gY = make_tensor(make_gmem_ptr(yrow), make_shape(N), make_stride(Int<1>{}));
  Tensor gW = make_tensor(make_gmem_ptr(W),    make_shape(N), make_stride(Int<1>{}));
  Tensor gB = make_tensor(make_gmem_ptr(B),    make_shape(N), make_stride(Int<1>{}));
  const bool vec_ok = ((N & 3) == 0);
  const int64_t NV = vec_ok ? (N >> 2) : 0;
  Tensor gXv = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(xrow)),
                           make_shape(NV), make_stride(Int<1>{}));
  Tensor gYv = make_tensor(make_gmem_ptr(reinterpret_cast<float4*>(yrow)),
                           make_shape(NV), make_stride(Int<1>{}));
  Tensor gWv = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(W)),
                           make_shape(NV), make_stride(Int<1>{}));
  Tensor gBv = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(B)),
                           make_shape(NV), make_stride(Int<1>{}));
  const float shift = gX(0);
  const double invN = 1.0 / (double)N;
  const double md = dsum[row] * invN;
  double var = dsq[row] * invN - md * md;
  if (var < 0.0) var = 0.0;
  const float mean_d = (float)md;
  const float rstd = (float)(1.0 / sqrt(var + (double)eps));
  if (vec_ok) {
    const int64_t per = (NV + splits - 1) / splits;
    const int64_t vb = (int64_t)split * per;
    const int64_t ve = min(NV, vb + per);
    int64_t i = vb + tid;
    for (; i + 3 * kThreads < ve; i += 4 * kThreads) {
      stcs4(&gYv(i), norm4(ldcs4(&gXv(i)), ldg4(&gWv(i)), ldg4(&gBv(i)), shift, mean_d, rstd));
      stcs4(&gYv(i + kThreads), norm4(ldcs4(&gXv(i + kThreads)), ldg4(&gWv(i + kThreads)), ldg4(&gBv(i + kThreads)), shift, mean_d, rstd));
      stcs4(&gYv(i + 2 * kThreads), norm4(ldcs4(&gXv(i + 2 * kThreads)), ldg4(&gWv(i + 2 * kThreads)), ldg4(&gBv(i + 2 * kThreads)), shift, mean_d, rstd));
      stcs4(&gYv(i + 3 * kThreads), norm4(ldcs4(&gXv(i + 3 * kThreads)), ldg4(&gWv(i + 3 * kThreads)), ldg4(&gBv(i + 3 * kThreads)), shift, mean_d, rstd));
    }
    for (; i < ve; i += kThreads) {
      stcs4(&gYv(i), norm4(ldcs4(&gXv(i)), ldg4(&gWv(i)), ldg4(&gBv(i)), shift, mean_d, rstd));
    }
  } else {
    const int64_t per = (N + splits - 1) / splits;
    const int64_t b = (int64_t)split * per;
    const int64_t e = min(N, b + per);
    for (int64_t j = b + tid; j < e; j += kThreads) {
      float d = ldcs1(&gX(j)) - shift;
      stcs1(&gY(j), fmaf((d - mean_d) * rstd, ldg1(&gW(j)), ldg1(&gB(j))));
    }
  }
}
